Let $D := (1 / \sqrt{2}) \mathrm{diam} (\mathrm{supp}(
u))$. The probability measure $
u$ satisfies one or more of the following conditions:
     egin{itemize}
        \item[(i)]    $
u$ is $ eta$-semi-log-convex for some $ eta >0$ and $\kappa$-semi-log-concave for some $\kappa > 0$ with $\mathrm{supp}(
u) = {\mathbb{R}}^d$;
        \item[(ii)]   $
u$ is $\kappa$-semi-log-concave for some $\kappa \in {\mathbb{R}}$ with $D \in (0, \infty)$;
        \item[(iii)]  $
u = \gamma_{d, \sigma^2} * ho$  where $ho$ is a probability measure supported on a Euclidean ball of radius $R$ on $\mathbb R^d$;
        \item[(iv)]   $
u$ is $ eta$-semi-log-convex for some $ eta >0$, $\kappa$-semi-log-concave for some $\kappa \le 0$, and $ rac{\mathrm{d} 
u}{\mathrm{d} \gamma_d}(x)$ is $L$-log-Lipschitz in $x$ for some $L \ge 0$ with $\mathrm{supp}(
u) = {\mathbb{R}}^d$.
    \end{itemize}

Let $\nu(\mathrm{d} y) = p_1(y) \mathrm{d} y$ be a probability measure on ${\mathbb{R}}^d$ with\\
 $D := (1/\sqrt{2}) \mathrm{diam} (\mathrm{supp}(\nu))$.
\begin{itemize}
    \item[(a)] For any $t\in (0,1)$,
    \begin{equation*}
        \frac{\dot{a}_t}{a_t} {\mathbf{I}}_d \preceq \nabla_x v(t, x) \preceq \left\{ \frac{b_t (a_t \dot{b}_t - \dot{a}_t b_t)}{a_t^3} D^2 + \frac{\dot{a}_t} {a_t} \right\} {\mathbf{I}}_d.
    \end{equation*}

    \item[(b)] Suppose that $p_1$ is $\beta$-semi-log-convex with $\beta > 0$ and $\mathrm{supp}(p_1) = {\mathbb{R}}^d$. Then for any $t\in (0, 1]$,
    \begin{equation*}
        \nabla_x v(t, x) \succeq \frac{\beta a_t \dot{a}_t + b_t \dot{b}_t} {\beta a_t^2 + b_t^2} {\mathbf{I}}_d.
    \end{equation*}

    \item[(c)] Suppose that $p_1$ is $\kappa$-semi-log-concave with $\kappa \in {\mathbb{R}}$. Then for any $t \in (t_0, 1]$,
    \begin{align*}
        \nabla_x v(t, x) \preceq \frac{\kappa a_t \dot{a}_t + b_t \dot{b}_t} {\kappa a_t^2 + b_t^2} {\mathbf{I}}_d,
    \end{align*}
    where $t_0$ is the root of the equation $\kappa + \frac{b_t^2}{a_t^2} = 0$ over $t \in (0, 1)$ if $\kappa < 0$ and $t_0 = 0$ if $\kappa \ge 0$.

    \item[(d)] Fix a probability measure $\rho$ on ${\mathbb{R}}^d$ supported on a Euclidean ball of radius $R$, and let $\nu := \gamma_{d, \sigma^2} * \rho$ with $\sigma > 0$. Then for any $t \in (0, 1)$,
    \begin{equation*}
        \frac{\dot{a}_t a_t + \sigma^2 \dot{b}_t b_t}{a_t^2 + \sigma^2 b_t^2} {\mathbf{I}}_d
        \preceq \nabla_x v(t, x) \preceq
        \left\{ \frac{a_t b_t (a_t \dot{b}_t - \dot{a}_t b_t)}{(a_t^2 + \sigma^2 b_t^2)^2} R^2 + \frac{\dot{a}_t a_t + \sigma^2 \dot{b}_t b_t}{a_t^2 + \sigma^2 b_t^2} \right\} {\mathbf{I}}_d.
    \end{equation*}

    \item[(e)] Suppose that $\frac{\mathrm{d} \nu}{\mathrm{d} \gamma_d}(x)$ is $L$-log-Lipschitz for some $L \ge 0$. Then for any $t \in (0, 1)$,
    \begin{align*}
        & \left\{ \left( \tfrac{\dot{b}_t}{b_t} a_t^2 - \dot{a}_t a_t \right) \left( -B_t - L^2 \left( \tfrac{b_t}{a_t^2 + b_t^2} \right)^2 \right) + \tfrac{\dot{a}_t a_t + \dot{b}_t b_t}{a_t^2 + b_t^2} \right\} {\mathbf{I}}_d \\
        & \preceq \nabla_x v(t, x)
          \preceq \left\{ \left( \tfrac{\dot{b}_t}{b_t} a_t^2 - \dot{a}_t a_t \right) B_t + \tfrac{\dot{a}_t a_t + \dot{b}_t b_t}{a_t^2 + b_t^2} \right\} {\mathbf{I}}_d,
    \end{align*}
    where $B_t := 5L b_t (a_t^2 + b_t^2)^{-\frac32} (L + (\log (\sqrt{a_t^2 + b_t^2}/b_t))^{-\frac12})$.
\end{itemize}

Suppose that Assumptions 1 and 2-(i) hold.
\begin{itemize}
    \item[(i)] If $\nu$ is $\kappa$-semi-log-concave for some $\kappa > 0$, then the flow map $X_1(x)$ is a Lipschitz mapping, that is,
    \begin{equation*}
\Vert \nabla_x X_1(x) \Vert_{2,2} \le \frac{1}{\sqrt{\kappa a_0^2 + b_0^2}}, \quad \forall x \in {\mathbb{R}}^d.
    \end{equation*}
    In particular, if $a_0 = 1$ and $b_0 = 0$, then
    \begin{equation*}
        \Vert \nabla_x X_1(x) \Vert_{2,2} \le \frac{1} {\sqrt{\kappa}}, \quad \forall x \in {\mathbb{R}}^d.
    \end{equation*}

    \item[(ii)] If $\nu$ is $\beta$-semi-log-convex for some $\beta >0$, then the time-reversed flow map $X^{*}_1(x)$ is a Lipschitz mapping, that is,
    \begin{equation*}
        \Vert \nabla_x X^{*}_1(x) \Vert_{2,2} \le \sqrt{\beta a_0^2 + b_0^2}, \quad \forall x \in \mathrm{supp}(\nu).
    \end{equation*}
    In particular, if $a_0 = 1$ and $b_0 = 0$, then
    \begin{equation*}
        \Vert \nabla_x X^{*}_1(x) \Vert_{2,2} \le \sqrt{\beta}, \quad \forall x \in \mathrm{supp}(\nu).
    \end{equation*}
\end{itemize}

Suppose that Assumptions 1 and 2-(iii) hold.
Then the flow map $X_1(x)$ is a Lipschitz mapping, that is,
\begin{equation*}
    \Vert \nabla_x X_1(x) \Vert_{2,2} \leq \frac{\sigma}{\sqrt{a_0^2 + \sigma^2 b_0^2}} \exp \left( \frac{a_0^2}{a_0^2 + \sigma^2 b_0^2} \cdot \frac{R^2}{2 \sigma^2} \right), \quad \forall x \in {\mathbb{R}}^d.
\end{equation*}
In particular, if $a_0 = 1$ and $b_0 = 0$, then
\begin{equation*}
    \Vert \nabla_x X_1(x) \Vert_{2,2} \leq \sigma \exp \left( \frac{R^2}{2 \sigma^2} \right), \quad \forall x \in {\mathbb{R}}^d.
\end{equation*}
Moreover, the time-reversed flow map $X^{*}_1(x)$ is a Lipschitz mapping, that is,
\begin{equation*}
    \Vert \nabla_x X^{*}_1(x) \Vert_{2,2} \le \sqrt{\sigma^{-2} a_0^2 + b_0^2}, \quad \forall x \in \mathrm{supp}(\nu).
\end{equation*}
In particular, if $a_0 = 1$ and $b_0 = 0$, then
\begin{equation*}
    \Vert \nabla_x X^{*}_1(x) \Vert_{2,2} \le \frac{1}{\sigma}, \quad \forall x \in \mathrm{supp}(\nu).
\end{equation*}

Suppose Assumptions 1 and 2-(i), (iii), or (iv) hold for a target measure $\nu$.
The Gaussian interpolation flow $(X_t)_{t \in [0, 1]}$ and its time-reversed flow $(X_t^*)_{t \in [0, 1]}$ form an auto-encoder with a Lipschitz encoder $X_1^*(x)$ and a Lipschitz decoder $X_1(x)$. The auto-encoding property holds in the sense that
\begin{equation}

    X_1 \circ X_1^* = {\mathbf{I}}_d.
\end{equation}

Suppose Assumptions 1 and 2-(i), (iii), or (iv) hold for the target measures $\nu_1$ and $\nu_2$.
For the target measure $\nu_1$, we define the Gaussian interpolation flow $(X_{1, t})_{t \in [0, 1]}$ and its time-reversed flow $(X_{1, t}^*)_{t \in [0, 1]}$.
We also define the Gaussian interpolation flow $(X_{2, t})_{t \in [0, 1]}$ and its time-reversed flow $(X_{2, t}^*)_{t \in [0, 1]}$ for the target measure $\nu_2$ using the same $a_t$ and $b_t$.
Then the transport maps $X_{1, 1}(x)$, $X_{1, 1}^*(x)$, $X_{2, 1}(x)$, and $X_{2, 1}^*(x)$ are Lipschitz continuous in the space variable $x$. Furthermore, the cycle consistency property holds in the sense that
\begin{equation}

    X_{1, 1} \circ X_{2, 1}^* \circ X_{2, 1} \circ X_{1, 1}^* = {\mathbf{I}}_d.
\end{equation}

Suppose Assumptions 1 and 2-(i), (iii), or (iv) hold.
If the source measure $\mu = \mathrm{Law}(a_0 \mathsf{Z} + b_0 \mathsf{X}_1)$ is replaced with the Gaussian measure $\gamma_{d, a_0^2}$,
then the stability of the transport map $X_1$ is guaranteed by the $W_2$ distance between the push-forward measure ${X_1}_{\#} \gamma_{d, a_0^2}$ and the target measure $\nu = \mathrm{Law}(\mathsf{X}_1)$ as follows
\begin{equation}

    W_2({X_1}_{\#} \gamma_{d, a_0^2}, \nu) \le C_1 b_0 \sqrt{\mathbb{E}_{\nu} [\Vert \mathsf{X_1} \Vert^2]} \exp (C_2 d).
\end{equation}

Suppose Assumptions 1 and 2 hold. Let $\tilde{q}_t$ denote the density function of ${Y_t}_{\#} \mu$.
\begin{itemize}
\item[(i)] Suppose that
\begin{equation}

    \int_0^1 \int_{{\mathbb{R}}^d} \Vert v(t, x) - \tilde{v}(t, x) \Vert^2 \tilde{q}_t(x) \mathrm{d} x \mathrm{d} t \le \varepsilon.
\end{equation}
Then
\begin{equation}

    W_2^2({Y_1}_{\#} \mu, \nu) \le \varepsilon \int_0^1 \exp \left( 2 \int_s^1 \theta_u \mathrm{d} u \right) \mathrm{d} s.
\end{equation}
\item[(ii)] Suppose that
\begin{equation*}
    \sup_{(t, x) \in [0, 1] \times {\mathbb{R}}^d} \Vert \nabla_x \tilde{v}(t, x) \Vert_{2,2} \le C_3.
\end{equation*}
Then
\begin{equation}

    W_2^2({Y_1}_{\#} \mu, \nu) \le \frac{\exp(2 C_3) - 1}{2 C_3} \int_0^1 \int_{{\mathbb{R}}^d} \Vert v(t, x) - \tilde{v}(t, x) \Vert^2 p_t(x) \mathrm{d} x \mathrm{d} t.
\end{equation}
\end{itemize}
